def can_partition(nums: list[int]) -> bool:
    _sum = sum(nums)
    div, mod = divmod(_sum, 2)
    if mod == 1:
        return False

    target = [div] * 2
    nums.sort(reverse=True)
    _len = len(nums)

    def dfs(index: int, target: list[int]) -> bool:
        if index == _len:
            return True
        num = nums[index]
        for i in range(2):
            if target[i] >= num:
                target[i] -= num
                if dfs(index + 1, target):
                    return True
                target[i] += num
        return False

