    S = N
    N_len = len(S)
    dp = [[[0 for _ in range(2)] for _ in range(K + 1)] for _ in range(N_len + 1)]
    dp[0][0][0] = 1

    for i in range(N_len):
        for j in range(K + 1):
            for k in range(2):
